        nro: idx + 1,
        fechaNormalizada: dateFromRow(row),
        materialNormalizado: materialName(row),
        familiaNormalizada: familyFromMaterial(row),
        kgCalculado: r0(kgFromRow(row)),
        tnCalculado: kgToTn(kgFromRow(row)),
        grupoCompraPlan: grupoCompra || "FUERA MIX",
        mixComponenteKey: grupoCompra,
        dentroMix: !!grupoCompra,
        productoKeyCalculado: productoKey || "",
        ramaCalculada: (producto && producto.nombre) || "",
        subramaCalculada: (subrama && subrama.nombre) || "",
        obsNormalizada: obsFromRow(row)
      };
      Object.keys(row || {}).sort().forEach(k => {
        out[k] = row[k];
      });
      return out;
    });
  }

function realRowsByMaterial(rows) {
  const byMaterial = {};
  (rows || []).forEach(row => {
    const material = normText(materialName(row));
    if (!material) return;
    byMaterial[material] = r0((byMaterial[material] || 0) + kgFromRow(row));
  });
  return byMaterial;
}

function compraGrupoFromProductoKey(productoKey, row, criteria) {
  const key = String(productoKey || "").toUpperCase();
  const producto = productoByKey(criteria || {}, key);
  const tipo = String((producto && producto.tipo) || "").toLowerCase();
  const nombreProducto = normText((producto && producto.nombre) || "");
  const fam = normText(familyFromMaterial(row));
  const mat = normText(materialName(row));
  const texto = key + " " + nombreProducto + " " + fam + " " + mat;

  // La categoria se decide por el material/familia comprado. Estar en Limbo
  // estructural no impide reconocer una Mezcla, Stretch u otra categoria.
  if (fam === "MEZCLA" || texto.includes("MEZCLA")) return "MEZCLA";
  if (fam === "STRETCH" || texto.includes("STRETCH") || texto.includes("STRECH") || texto.includes("FILM DE BAJA")) return "STRETCH";
  if (texto.includes("PP HOMO") || texto.includes("BAZAR TUTY") || texto.includes("BAZAR TUTTY")) return "PP HOMO";
  if (
    texto.includes("PP COPO") ||
    texto.includes("BALDE") ||
    texto.includes("BAZAR") ||
    texto.includes("TAPITA") ||
    texto.includes("TAPON") ||
    texto.includes("SILLA") ||
    fam === "NEGRO" ||
    fam === "PP"
  ) return "PP COPO";
  if (fam === "SOPLADO" || texto.includes("SOPLADO")) return "SOPLADO";
  if (
    tipo === "plan" ||
    key === "PEMD" || key === "ROTOMOLDEO" ||
    fam === "ADI" || fam === "ROTOMOLDEO" ||
    texto.includes("PEMD") || texto.includes("PEAD") || texto.includes("ROTOMOLDEO")
  ) return "PEAD";
  return "";
}

function subramaIdForRealRow(row, criteria, productoObj) {
  const material = materialName(row);
  let subId = subramaIdForMaterial(criteria || {}, material, productoObj.id);
  if (subId > 0) return subId;
  const fam = normText(familyFromMaterial(row));
  const estado = normText(row && (row.Estado ?? row.estado ?? ""));
  const color = normText(row && (row.Color ?? row.color ?? ""));
  const subs = subramasForProduct(criteria || {}, productoObj.id);
  const direct = subs.find(s => {
    const name = normText(s.nombre);
    return name && (name === fam || name === estado || name === color);
  });
  return direct ? r0(direct.id) : subId;
}

function productoKeyForRealRow(row, criteria) {
  const material = materialName(row);
  const assigned = criteria && criteria.asignacionesMaterial ? criteria.asignacionesMaterial[normText(material)] : null;
  if (assigned !== undefined && assigned !== null) return productoById(criteria, assigned).key;
  const mapped = criteria && criteria.materialMap ? (criteria.materialMap[normText(material)] || criteria.materialMap[material]) : null;
  if (mapped) return mapped.productoCompra || mapped.producto || mapped.key || mapped;
  const banda = findBandaMaterial(material, criteria || {});
  if (banda && banda.productoCompra) return banda.productoCompra;
  return inferProductKeyForStockMaterial(row, criteria || {});
}

function grupoCompraPlanFromRow(row, criteria) {
  return compraGrupoFromProductoKey(productoKeyForRealRow(row, criteria || {}), row, criteria || {});
}

function realRowsMix(rows, criteria) {
  const porGrupo = { "FUERA MIX": 0 };
  mixComponentsFromTree(criteria || {}, (criteria && criteria.mixComponentes) || []).forEach(x => { porGrupo[x.key] = 0; });
  const porMaterialDentro = {};
  const porMaterialFuera = {};
  (rows || []).forEach(row => {
    const kg = kgFromRow(row);
    if (!kg) return;
    const material = normText(materialName(row)) || "SIN MATERIAL";
    const productoKey = productoKeyForRealRow(row, criteria || {});
    const producto = productoByKey(criteria || {}, productoKey);
    const subramaId = subramaIdForRealRow(row, criteria || {}, producto);
    const candidato = producto && Number(producto.id) > 0 ? mixComponentKey(producto.id, subramaId) : "";
    const grupo = Object.prototype.hasOwnProperty.call(porGrupo, candidato) ? candidato : "";
    if (!grupo) {
      porGrupo["FUERA MIX"] = r0((porGrupo["FUERA MIX"] || 0) + kg);
      porMaterialFuera[material] = r0((porMaterialFuera[material] || 0) + kg);
      return;
    }
    porGrupo[grupo] = r0((porGrupo[grupo] || 0) + kg);
    porMaterialDentro[material] = r0((porMaterialDentro[material] || 0) + kg);
  });
  return { porGrupo, porMaterialDentro, porMaterialFuera };
}

function realRowsByCompraGrupo(rows, criteria) {
  return realRowsMix(rows, criteria).porGrupo;
}

function realRowsByProductoSubrama(rows, criteria) {
  const out = { porRamaKey: {}, porSubramaKey: {}, porMaterialRamaKey: {} };
  (rows || []).forEach(row => {
    const kg = kgFromRow(row);
    if (!kg) return;
    const material = materialName(row);
    const productoKey = productoKeyForRealRow(row, criteria || {});
    const productoObj = productoByKey(criteria || {}, productoKey);
    const subramaId = subramaIdForRealRow(row, criteria || {}, productoObj);
    const subrama = subramaById(criteria || {}, productoObj.id, subramaId);
    const ramaKey = productoObj.key || productoKey || "";
    const subKey = ramaKey + "||" + (subrama.nombre || "");
    const matKey = ramaKey + "||" + normText(material);
    out.porRamaKey[ramaKey] = r0((out.porRamaKey[ramaKey] || 0) + kg);
    out.porSubramaKey[subKey] = r0((out.porSubramaKey[subKey] || 0) + kg);
    out.porMaterialRamaKey[matKey] = r0((out.porMaterialRamaKey[matKey] || 0) + kg);
  });
  return out;
}

function indexStockByProduct(stockDb, criteria) {
  const byProduct = {};
  const componentsByProduct = {};
  const revisar = [];
  const componentByKey = {};
  stockRows(stockDb).forEach(row => {
    const material = materialName(row) || "SIN MATERIAL";
    const banda = findBandaMaterial(material, criteria || {});
    const producto = productForStockMaterial(row, criteria);
    const productoObj = productoByKey(criteria, producto);
    const subramaId = subramaIdForMaterial(criteria, material, productoObj.id);
    const subrama = subramaById(criteria, productoObj.id, subramaId);
    const sugeridoKey = inferProductKeyForStockMaterial(row, criteria);
    const sugeridoObj = productoByKey(criteria, sugeridoKey);
    const fam = (banda && banda.familiaOperativa) || familyFromMaterial(row);
    const kg = kgFromRow(row);
    const estadosKg = stockEstadoKilos(row);
    const minimoKg = banda ? tnToKg(banda.minimoTn) : minKgFromRow(row);
    const maximoKg = banda ? tnToKg(banda.maximoTn) : 0;
    const deficitKg = Math.max(0, minimoKg - kg);
    const excesoKg = maximoKg > 0 ? Math.max(0, kg - maximoKg) : (kg > 0 ? kg : 0);
    const comp = {
      material,
      familia: fam,
      producto,
      productoId: productoObj.id,
      productoNombre: productoObj.nombre,
      subramaId,
      subramaNombre: subrama.nombre,
      sugeridoKey,
      sugeridoId: sugeridoObj.id,
      sugeridoNombre: sugeridoObj.nombre,
      obs: obsFromRow(row),
      stockTn: kgToTn(kg),
      paraMolerTn: kgToTn(estadosKg.paraMolerKg),
      paraLavarTn: kgToTn(estadosKg.paraLavarKg),
      lavadoTn: kgToTn(estadosKg.lavadoKg),
      extruidoTn: kgToTn(estadosKg.extruidoKg),
      totalEstadosTn: kgToTn(estadosKg.totalEstadosKg),
      minimoTn: kgToTn(minimoKg),
      maximoTn: kgToTn(maximoKg),
      deficitTn: kgToTn(deficitKg),
      excesoTn: kgToTn(excesoKg),
      estado: excesoKg > 0 ? "sobra" : (minimoKg > 0 ? (kg < minimoKg ? "critico" : "ok") : "sin_minimo")
    };
    byProduct[producto] = (byProduct[producto] || 0) + kg;
    if (!componentsByProduct[producto]) componentsByProduct[producto] = [];
    const compKey = producto + "||" + normText(material);
    const previo = componentByKey[compKey];
    if (previo) {
      previo.stockTn = r1(n(previo.stockTn) + n(comp.stockTn));
      previo.paraMolerTn = r1(n(previo.paraMolerTn) + n(comp.paraMolerTn));
      previo.paraLavarTn = r1(n(previo.paraLavarTn) + n(comp.paraLavarTn));
      previo.lavadoTn = r1(n(previo.lavadoTn) + n(comp.lavadoTn));
      previo.extruidoTn = r1(n(previo.extruidoTn) + n(comp.extruidoTn));
      previo.totalEstadosTn = r1(n(previo.paraMolerTn) + n(previo.paraLavarTn) + n(previo.lavadoTn) + n(previo.extruidoTn));
      previo.minimoTn = Math.max(n(previo.minimoTn), n(comp.minimoTn));
      previo.maximoTn = Math.max(n(previo.maximoTn), n(comp.maximoTn));
      previo.deficitTn = r1(Math.max(0, n(previo.minimoTn) - n(previo.stockTn)));
      previo.excesoTn = n(previo.maximoTn) > 0 ? r1(Math.max(0, n(previo.stockTn) - n(previo.maximoTn))) : 0;
      previo.estado = n(previo.excesoTn) > 0 ? "sobra" : (n(previo.minimoTn) > 0 ? (n(previo.stockTn) < n(previo.minimoTn) ? "critico" : "ok") : "sin_minimo");
      const obsNueva = String(comp.obs || "").trim();
      if (obsNueva && !String(previo.obs || "").includes(obsNueva)) previo.obs = [previo.obs, obsNueva].filter(Boolean).join(" | ");
    } else {
      componentByKey[compKey] = comp;
      componentsByProduct[producto].push(comp);
      if (producto === "LIMBO") revisar.push(comp);
    }
  });
  Object.keys(componentsByProduct).forEach(k => {
    componentsByProduct[k].sort((a, b) => b.deficitTn - a.deficitTn || b.stockTn - a.stockTn || a.material.localeCompare(b.material));
  });
  return { byProduct, componentsByProduct, revisar };
}
function agendaRows(agendaDb, mesKey) {
  const rows = [];
  if (!agendaDb || typeof agendaDb !== "object") return rows;
  if (Array.isArray(agendaDb.turnos)) rows.push(...agendaDb.turnos.filter(x => !x.mesKey || x.mesKey === mesKey));
  if (Array.isArray(agendaDb.resumenRamaColor)) rows.push(...agendaDb.resumenRamaColor);
  if (Array.isArray(agendaDb.items)) rows.push(...agendaDb.items);
  return rows;
}

function sumFamilies(idx, families) {
  return (families || []).reduce((sum, f) => sum + (idx.byFamily[normFamilia(f)] || 0), 0);
}
function bandaGrupoKeyFor(productoKey, subramaNombre) {
  return normText(productoKey || "RAMA").replace(/\s+/g, "_") + "_SUB_" + normText(subramaNombre || "SIN_SUBRAMA").replace(/\s+/g, "_");
}

function bandaGrupoMatches(banda, producto, subrama, material) {
  const prodKey = normText(producto && producto.key);
  const prodName = normText(producto && producto.nombre);
  const subName = normText(subrama && subrama.nombre);
  const bandaProd = normText(banda.productoKey || banda.producto || banda.ramaKey || banda.rama);
  const bandaSub = normText(banda.subramaNombre || banda.subrama || banda.nombreSubrama);
  const matKey = normText(material && material.material);
  const mats = Array.isArray(banda.materiales) ? banda.materiales.map(normText) : [];
  const prodOk = !bandaProd || bandaProd === prodKey || bandaProd === prodName;
  const subOk = !bandaSub || bandaSub === subName;
  const matOk = !mats.length || mats.includes(matKey);
  return prodOk && subOk && matOk;
}

function applyBandasGrupo(criteria, producto, subrama, mats, candidatos) {
  const bandas = Array.isArray(criteria.bandasGrupo) ? criteria.bandasGrupo : [];
  const usados = {};
  const grupos = [];
  bandas.forEach(banda => {
    const miembros = (candidatos || mats || []).filter(m => !usados[normText(m.material)] && bandaGrupoMatches(banda, producto, subrama, m));
    if (!miembros.length) return;
    const totalKg = miembros.reduce((s, m) => s + tnToKg(m.stockTn), 0);
    const minimoKg = tnToKg(banda.minimoTn);
    const maximoKg = tnToKg(banda.maximoTn);
    const deficitKg = Math.max(0, minimoKg - totalKg);
    const excesoKg = maximoKg > 0 ? Math.max(0, totalKg - maximoKg) : 0;
    miembros.forEach(m => {
      usados[normText(m.material)] = true;
      m.bandaGrupoKey = banda.key;
      m.bandaGrupoNombre = banda.nombre || banda.subramaNombre || subrama.nombre;
      m.bandaGrupoModo = "sumatoria";
      m.bandaGrupoMinimoTn = kgToTn(minimoKg);
      m.bandaGrupoMaximoTn = kgToTn(maximoKg);
      m.bandaGrupoStockTn = kgToTn(totalKg);
      m.bandaGrupoDeficitTn = kgToTn(deficitKg);
      m.bandaGrupoExcesoTn = kgToTn(excesoKg);
      m.minimoOriginalTn = m.minimoTn;
      m.maximoOriginalTn = m.maximoTn;
      m.deficitOriginalTn = m.deficitTn;
      m.excesoOriginalTn = m.excesoTn;
      m.minimoTn = 0;
      m.maximoTn = 0;
      m.deficitTn = 0;
      m.excesoTn = 0;
      m.estado = "banda_grupo";
    });
    grupos.push({
      key: banda.key,
      nombre: banda.nombre || banda.subramaNombre || subrama.nombre,
      minimoTn: kgToTn(minimoKg),
      maximoTn: kgToTn(maximoKg),
      stockTn: kgToTn(totalKg),
      deficitTn: kgToTn(deficitKg),
      excesoTn: kgToTn(excesoKg),
      margenSobreMinimoTn: kgToTn(Math.max(0, totalKg - minimoKg)),
      hastaMaximoTn: maximoKg > 0 ? kgToTn(Math.max(0, maximoKg - totalKg)) : 0,
      dentroDeRango: totalKg >= minimoKg && (maximoKg <= 0 || totalKg <= maximoKg),
      materiales: [...new Set(miembros.map(m => m.material))]
    });
  });
  const libres = (mats || []).filter(m => !usados[normText(m.material)]);
  return { libres, grupos };
}

function stockComponents(idx, families, bandas) {
  const bandByFamily = {};
  (bandas || []).forEach(b => { bandByFamily[normFamilia(b.familia)] = b; });
  return (families || []).map(f => {
    const fam = normFamilia(f);
    const stockKg = idx.byFamily[fam] || 0;
    const banda = bandByFamily[fam] || null;
    const minimoKg = banda ? tnToKg(banda.minimoTn) : (idx.minByFamily[fam] || 0);
    const idealKg = banda ? tnToKg(banda.idealTn || banda.minimoTn) : minimoKg;
    const maximoKg = banda ? tnToKg(banda.maximoTn || 0) : 0;
    const deficitKg = Math.max(0, minimoKg - stockKg);
    let estado = "sin_minimo";
    if (minimoKg > 0) {
      if (stockKg < minimoKg) estado = "critico";
      else if (idealKg > minimoKg && stockKg < idealKg) estado = "justo";
      else if (maximoKg > 0 && stockKg > maximoKg) estado = "alto";
      else estado = "ok";
    }
    return {
      familia: fam,
      stockTn: kgToTn(stockKg),
      minimoTn: kgToTn(minimoKg),
      idealTn: kgToTn(idealKg),
      maximoTn: kgToTn(maximoKg),
      deficitTn: kgToTn(deficitKg),
      estado
    };
  }).filter(x => x.stockTn || x.minimoTn);
}
function sumBand(idx, band) {
  const fam = normFamilia(band.familia);
  return (band.colores || []).reduce((sum, c) => sum + (idx.byFamilyColor[fam + "||" + normColor(c)] || 0), 0);
}

function buildDashboard(criteria, realDb, stockDb, agendaDb, aviso) {
  const mesKey = validMes(criteria.mesKey) ? criteria.mesKey : mesActual();
  const realesRows = collectRows(realDb, mesKey);
  const stockInfo = stockSourceInfo(stockDb);
  const stockCutDate = stockInfo.fechaStockNormalizada || parseDateKey(stockInfo.fechaStock);
  const realesDesdeStockRows = rowsFromDateInclusive(realesRows, stockCutDate);
  const realesIdx = indexKg(realesRows);
  const realesPostStockIdx = indexKg(realesDesdeStockRows);
  const stockIdx = indexKg(stockRows(stockDb));
  const stockProductos = indexStockByProduct(stockDb, criteria);
  const agendaIdx = indexKg(agendaRows(agendaDb, mesKey));

  const plan = (criteria.planFamilias || []).map(rule => {
    const objetivoKg = tnToKg(rule.objetivoTn);
    const realKg = sumFamilies(realesIdx, rule.familias);
    const realPostStockKg = sumFamilies(realesPostStockIdx, rule.familias);
    const agendaKg = sumFamilies(agendaIdx, rule.familias);
    const stockKg = stockProductos.byProduct[rule.key] || sumFamilies(stockIdx, rule.familias);
    const componentesStock = stockProductos.componentsByProduct[rule.key] || stockComponents(stockIdx, rule.familias, rule.stockBandas);
    const stockDeficitTn = r1(componentesStock.reduce((s, x) => s + x.deficitTn, 0));
    const stockEstado = componentesStock.some(x => x.estado === "critico") ? "critico" :
      (componentesStock.some(x => x.estado === "justo") ? "justo" : "ok");
    const cubiertoKg = realKg + agendaKg;
    const faltanteKg = Math.max(0, objetivoKg - cubiertoKg);
    let estado = "comprar";
    let accion = "Llamar proveedores";
    if (faltanteKg <= 0) { estado = "ok"; accion = "No comprar por plan"; }
    else if (faltanteKg <= objetivoKg * 0.15) { estado = "mirar"; accion = "Completar fino"; }
    return {
      key: rule.key,
      nombre: rule.nombre,
      objetivoTn: r1(rule.objetivoTn),
      realTn: kgToTn(realKg),
      realPostStockTn: kgToTn(realPostStockKg),
      agendaTn: kgToTn(agendaKg),
      stockTn: kgToTn(stockKg),
      cubiertoTn: kgToTn(cubiertoKg),
      faltanteTn: kgToTn(faltanteKg),
      avance: objetivoKg > 0 ? Math.min(1, cubiertoKg / objetivoKg) : 0,
      familias: rule.familias || [],
      componentesStock,
      stockDeficitTn,
      stockEstado,
      foco: rule.foco || "",
      criterio: rule.criterio || "",
      estado,
      accion
    };
  });

  const bandas = (criteria.bandasStock || []).map(rule => {
    const stockKg = sumBand(stockIdx, rule);
    const agendaKg = sumBand(agendaIdx, rule);
    const disponibleKg = stockKg + agendaKg;
    const minKg = tnToKg(rule.minimoTn);
    const idealKg = tnToKg(rule.idealTn);
    const maxKg = tnToKg(rule.maximoTn);
    let estado = "ok";
    let accion = "Mantener";
    let sugeridoKg = 0;
    if (disponibleKg < minKg) {
      estado = "urgente";
      sugeridoKg = Math.max(0, idealKg - disponibleKg);
      accion = "Comprar hasta volver a banda";
    } else if (disponibleKg > maxKg) {
      estado = "frenar";
      accion = "Frenar compras";
    }
    return {
      key: rule.key,
      nombre: rule.nombre,
      familia: rule.familia,
      colores: rule.colores || [],
      minimoTn: r1(rule.minimoTn),
      idealTn: r1(rule.idealTn),
      maximoTn: r1(rule.maximoTn),
      stockTn: kgToTn(stockKg),
      agendaTn: kgToTn(agendaKg),
      disponibleTn: kgToTn(disponibleKg),
      sugeridoTn: kgToTn(sugeridoKg),
      estado,
      accion,
      criterio: rule.criterio || ""
    };
  });

  const controles = (criteria.controlStock || []).map(rule => {
    const componentes = stockProductos.componentsByProduct[rule.key] || [];
    const stockTn = r1(componentes.reduce((s, x) => s + x.stockTn, 0));
    const minimoTn = r1(componentes.reduce((s, x) => s + x.minimoTn, 0));
    const deficitTn = r1(componentes.reduce((s, x) => s + x.deficitTn, 0));
    const estado = deficitTn > 0 ? "revisar" : (stockTn > 0 ? "ok" : "sin_stock");
    return {
      key: rule.key,
      nombre: rule.nombre,
      criterio: rule.criterio || "",
      stockTn,
      minimoTn,
      deficitTn,
      estado,
      componentes
    };
  }).filter(x => x.stockTn || x.minimoTn || x.componentes.length);

  const objetivoTotalTn = plan.reduce((s, x) => s + x.objetivoTn, 0);
  const realTotalTn = r1(plan.reduce((s, x) => s + x.realTn, 0));
  const agendaTotalTn = r1(plan.reduce((s, x) => s + x.agendaTn, 0));
  const faltanteTotalTn = r1(plan.reduce((s, x) => s + x.faltanteTn, 0));
  const tareas = []
    .concat(bandas.filter(x => x.estado === "urgente").map(x => ({
      prioridad: 1,
      tipo: "banda_stock",
      titulo: x.nombre,
      accion: x.accion,
      tn: x.sugeridoTn,
      motivo: "Stock por debajo de " + x.minimoTn + " tn"
    })))
    .concat(plan.filter(x => x.faltanteTn > 0 || x.stockDeficitTn > 0).map(x => ({
      prioridad: x.stockDeficitTn > 0 ? 1 : (x.estado === "comprar" ? 2 : 3),
      tipo: "plan_mensual",
      titulo: x.nombre,
      accion: x.accion,
      tn: Math.max(x.faltanteTn, x.stockDeficitTn || 0),
      motivo: x.stockDeficitTn > 0 ? ("Stock interno abajo de minimo: " + x.stockDeficitTn + " tn") : "Faltante contra objetivo mensual"
    })))
    .sort((a, b) => a.prioridad - b.prioridad || b.tn - a.tn);

  const stockMapeo = Object.values(stockProductos.componentsByProduct)
    .flat()
    .sort((a, b) => a.productoId - b.productoId || b.stockTn - a.stockTn || a.material.localeCompare(b.material));
  const stockPaneles = (criteria.productosTerminados || PRODUCTOS_TERMINADOS).map(p => {
    const materiales = stockMapeo
      .filter(m => Number(m.productoId) === Number(p.id))
      .sort((a, b) => a.subramaId - b.subramaId || b.stockTn - a.stockTn || a.material.localeCompare(b.material));
    const subramasBase = subramasForProduct(criteria, p.id);
    let subramas = subramasBase.map(s => {
      const mats = materiales
        .filter(m => Number(m.subramaId) === Number(s.id))
        .sort((a, b) => b.stockTn - a.stockTn || a.material.localeCompare(b.material));
      // Los candidatos son todos los materiales de la rama: el JSON puede agrupar vecinos de otras subramas.
      const bandaEval = applyBandasGrupo(criteria, p, s, mats, materiales);
      const libres = bandaEval.libres || [];
      const grupos = bandaEval.grupos || [];
      const totalTn = r1(mats.reduce((sum, m) => sum + n(m.stockTn), 0));
      const minimoTn = r1(
        libres.reduce((sum, m) => sum + n(m.minimoTn), 0) +
        grupos.reduce((sum, g) => sum + n(g.minimoTn), 0)
      );
      const deficitTn = r1(
        libres.reduce((sum, m) => sum + n(m.deficitTn), 0) +
        grupos.reduce((sum, g) => sum + n(g.deficitTn), 0)
      );
      const excesoTn = r1(
        libres.reduce((sum, m) => sum + n(m.excesoTn), 0) +
        grupos.reduce((sum, g) => sum + n(g.excesoTn), 0)
      );
      const maximoTn = r1(
        libres.reduce((sum, m) => sum + n(m.maximoTn), 0) +
        grupos.reduce((sum, g) => sum + n(g.maximoTn), 0)
      );
      return {
        id: s.id,
        nombre: s.nombre,
        mostrarVacia: s.mostrarVacia === true,
        totalTn,
        minimoTn,
        maximoTn,
        deficitTn,
        excesoTn,
        cobertura: minimoTn > 0 ? Math.min(1, totalTn / minimoTn) : 1,
        estado: deficitTn > 0 ? "critico" : (excesoTn > 0 ? "sobra" : "ok"),
        bandasGrupo: grupos,
        materiales: mats
      };
    })
      // No dibujar subramas completamente vacias. Siguen existiendo en
      // subramasProducto y, por lo tanto, siguen disponibles como destino
      // en el selector para mover materiales.
      .filter(s =>
        n(s.totalTn) > 0 ||
        n(s.deficitTn) > 0 ||
        (Array.isArray(s.materiales) && s.materiales.length > 0) ||
        (Array.isArray(s.bandasGrupo) && s.bandasGrupo.length > 0) ||
        s.mostrarVacia === true
      )
      .sort((a, b) => b.totalTn - a.totalTn || Number(a.id) - Number(b.id));
    const panelTotalTn = r1(materiales.reduce((s, m) => s + n(m.stockTn), 0));
    subramas = subramas.map((s, idx) => Object.assign({}, s, {
      color: PIE_COLORS[idx % PIE_COLORS.length],
      pct: panelTotalTn > 0 ? r1((s.totalTn / panelTotalTn) * 100) : 0
    }));
    const pieParts = subramas.map(s => ({ value: s.totalTn, color: s.color }));
    return {
      id: p.id,
      key: p.key,
      nombre: p.nombre,
      tipo: p.tipo,
      mostrarVacia: p.mostrarVacia === true,
      totalTn: panelTotalTn,
      deficitTn: r1(subramas.reduce((s, sub) => s + n(sub.deficitTn), 0)),
      excesoTn: r1(subramas.reduce((s, sub) => s + n(sub.excesoTn), 0)),
      pieGradient: pieGradient(pieParts),
      subramas,
      materiales
    };
  })
    .filter(p => p.materiales.length || Number(p.id) === 0 || p.mostrarVacia === true)
    .sort((a, b) => b.totalTn - a.totalTn || Number(a.id) - Number(b.id));

  msg.payload = {
    version: 2,
    tipo: "cavernicola_tablero_v2",
    generadoEn: new Date().toISOString(),
    mesKey,
    aviso: aviso || "",
    mixMensual: Object.assign({ mesKey }, metaPlanSnapshot(criteria)),
    modeloCompras: criteria.modeloCompras || {},
    meta: {
      objetivoTotalTn,
      realTotalTn,
      agendaTotalTn,
      faltanteTotalTn,
      fuentes: {
        criterio: !!criteria.actualizado,
        reales: !!(realDb && Object.keys(realDb).length),
        stock: !!(stockDb && Object.keys(stockDb).length),
        agenda: !!(agendaDb && Object.keys(agendaDb).length)
      }
    },
    criterio: criteria,
    plan,
    bandas,
    controles,
    tareas,
    stockMapeo,
    stockPaneles,
    productosTerminados: criteria.productosTerminados || PRODUCTOS_TERMINADOS,
    stockRevisar: stockProductos.revisar,
    stockAuditoria: {
      fuente: STOCK_FILE,
      info: stockInfo,
      filas: stockAuditRows(stockDb, criteria)
    },
    realesAuditoria: {
      fuente: REALES_FILE,
      info: {
        mesKey,
        fechaStockCorte: stockInfo.fechaStock || "",
        fechaStockCorteNormalizada: stockCutDate,
        fechaStockOrigen: stockInfo.fechaStockOrigen || "",
        postStockModo: stockCutDate ? "desde_stock_inclusive" : "sin_fecha_stock",
        registrosMes: realesRows.length,
        registrosPostStock: realesDesdeStockRows.length
      },
      porMaterial: realRowsByMaterial(realesDesdeStockRows),
      porMaterialMes: realRowsByMaterial(realesRows),
      porMaterialDentroMixMes: realRowsMix(realesRows, criteria).porMaterialDentro,
      porMaterialFueraMixMes: realRowsMix(realesRows, criteria).porMaterialFuera,
      porGrupoCompra: realRowsByCompraGrupo(realesDesdeStockRows, criteria),
      porGrupoCompraMes: realRowsByCompraGrupo(realesRows, criteria),
      porProductoSubrama: realRowsByProductoSubrama(realesDesdeStockRows, criteria),
      porProductoSubramaMes: realRowsByProductoSubrama(realesRows, criteria),
      filasPostStock: realAuditRows(realesDesdeStockRows, criteria),
      filas: realAuditRows(realesRows, criteria)
    }
  };
  return msg;
}

